415: 	}
416: 	if !strings.Contains(cleanT, string(filepath.Separator)) && filepath.Base(cleanA) == cleanT {
417: 		return true
418: 	}
419: 	if !strings.Contains(cleanA, string(filepath.Separator)) && filepath.Base(cleanT) == cleanA {
