154: // HandleStop parses the raw JSON payload and handles the Stop event within the execution budget.
155: // It returns a standard JSON object string ("{}") on completion or no-op skip.
156: func HandleStop(ctx context.Context, rawPayload []byte, opts ...HookOption) ([]byte, error) {
157: 	if ctx == nil {
158: 		ctx = context.Background()
159: 	}
160: 	var payload StopPayload
161: 	if len(rawPayload) > 0 && strings.TrimSpace(string(rawPayload)) != "" {
162: 		if err := json.Unmarshal(rawPayload, &payload); err != nil {
163: 			return nil, fmt.Errorf("parsing Stop payload JSON: %w", err)
164: 		}
165: 	}
166: 	payload.Normalize()
167: 
168: 	_, err := HandleStopEvent(ctx, &payload, opts...)
169: 	if err != nil {
170: 		return nil, err
171: 	}
172: 
173: 	return []byte("{}"), nil
174: }
