176: // HandleStopEvent executes the complete Stop hook pipeline:
177: // 1. Enforces execution budget (≤ 200ms)
178: // 2. Evaluates kill-switch checks (REPO_MEMORY_DISABLED, machine config, repo config)
179: // 3. Evaluates REPO_MEMORY_HOUSEKEEPING guard (skipping housekeeping runs)
180: // 4. Evaluates enrolment checks (verifying the workspace is enrolled in registry)
181: // 5. Creates and writes a durable capture spool entry
182: // 6. Performs incremental transcript copying into queue/ with cursor state tracking
183: func HandleStopEvent(ctx context.Context, payload *StopPayload, opts ...HookOption) (*StopResult, error) {
184: 	start := time.Now()
185: 
186: 	opt := HookOptions{
187: 		Timeout: DefaultHookBudget,
188: 	}
189: 	for _, fn := range opts {
190: 		fn(&opt)
191: 	}
192: 
193: 	// 1. Budget enforcement (≤ 200ms)
194: 	budget := opt.Timeout
195: 	if budget <= 0 {
196: 		budget = DefaultHookBudget
197: 	}
198: 	if ctx == nil {
199: 		ctx = context.Background()
200: 	}
201: 	var cancel context.CancelFunc
202: 	if _, hasDeadline := ctx.Deadline(); !hasDeadline {
203: 		ctx, cancel = context.WithTimeout(ctx, budget)
204: 		defer cancel()
205: 	}
206: 
207: 	// 2. Kill-switch check (Step A: REPO_MEMORY_DISABLED env var)
208: 	if os.Getenv("REPO_MEMORY_DISABLED") == "1" || strings.EqualFold(os.Getenv("REPO_MEMORY_DISABLED"), "true") {
209: 		return &StopResult{
210: 			Skipped:  true,
211: 			Reason:   "kill-switch active (REPO_MEMORY_DISABLED)",
212: 			Duration: time.Since(start),
213: 		}, nil
214: 	}
215: 
216: 	// 3. REPO_MEMORY_HOUSEKEEPING guard (Step B: skip housekeeping runs per SPEC §6.2 / E07)
217: 	if os.Getenv("REPO_MEMORY_HOUSEKEEPING") == "1" || strings.EqualFold(os.Getenv("REPO_MEMORY_HOUSEKEEPING"), "true") {
218: 		return &StopResult{
219: 			Skipped:  true,
220: 			Reason:   "housekeeping run skipped (REPO_MEMORY_HOUSEKEEPING)",
221: 			Duration: time.Since(start),
222: 		}, nil
223: 	}
224: 
225: 	dataDir := opt.DataDir
226: 	if dataDir == "" {
227: 		dataDir = config.DataDir()
228: 	}
229: 
230: 	// 2. Kill-switch check (Step C: machine configuration enabled)
231: 	machCfg, err := config.LoadMachineConfig(dataDir)
232: 	if err != nil {
233: 		return nil, fmt.Errorf("loading machine config: %w", err)
234: 	}
235: 	if !machCfg.Enabled {
236: 		return &StopResult{
237: 			Skipped:  true,
238: 			Reason:   "kill-switch active (machine config disabled)",
239: 			Duration: time.Since(start),
240: 		}, nil
241: 	}
242: 
243: 	// Determine candidate workspace
244: 	workspace := opt.WorkspaceOverride
245: 	if workspace == "" && len(payload.WorkspacePaths) > 0 && payload.WorkspacePaths[0] != "" {
246: 		workspace = payload.WorkspacePaths[0]
247: 	}
248: 	if workspace == "" && payload.TranscriptPath != "" {
249: 		if root, err := gitops.FindRepoRoot(filepath.Dir(payload.TranscriptPath)); err == nil {
250: 			workspace = root
251: 		}
252: 	}
253: 	var convSummary *ConversationSummary
254: 	if (workspace == "" || payload.ParentConversationID == "") && payload.ConversationID != "" && (opt.AppDBPath != "" || opt.CliDBPath != "") {
255: 		var attrOpts []AttributionOption
256: 		if opt.AppDBPath != "" {
257: 			attrOpts = append(attrOpts, WithAppDBPath(opt.AppDBPath))
258: 		}
259: 		if opt.CliDBPath != "" {
260: 			attrOpts = append(attrOpts, WithCliDBPath(opt.CliDBPath))
261: 		}
262: 		convSummary, _ = LookupConversationSummary(payload.ConversationID, attrOpts...)
263: 		if workspace == "" && convSummary != nil && len(convSummary.WorkspacePaths) > 0 {
264: 			workspace = convSummary.WorkspacePaths[0]
265: 		}
266: 	}
267: 	if workspace == "" {
268: 		if wd, err := os.Getwd(); err == nil {
269: 			workspace = wd
270: 		}
271: 	}
272: 
273: 	// Additional housekeeping path guard: directory matching runs/<repo-id>
274: 	if isHousekeepingPath(workspace) {
275: 		return &StopResult{
276: 			Skipped:  true,
277: 			Reason:   "housekeeping directory skipped (runs/ path)",
278: 			Duration: time.Since(start),
279: 		}, nil
280: 	}
281: 
282: 	// 4. Enrolment check (Step D: verify repository enrolment in registry.json)
283: 	entry, found, err := config.FindRegistryEntry(dataDir, workspace)
284: 	if err != nil {
285: 		return nil, fmt.Errorf("querying registry: %w", err)
286: 	}
287: 	if !found || entry == nil {
288: 		return &StopResult{
289: 			Skipped:  true,
290: 			Reason:   "workspace not enrolled in registry",
291: 			Duration: time.Since(start),
292: 		}, nil
293: 	}
294: 
295: 	// 2. Kill-switch check (Step E: repository config enabled)
296: 	repoCfg, err := config.LoadRepoConfig(entry.RootPath)
297: 	if err != nil {
298: 		return nil, fmt.Errorf("loading repo config: %w", err)
299: 	}
300: 	if !repoCfg.IsEnabled() {
301: 		return &StopResult{
302: 			Skipped:  true,
303: 			Reason:   "kill-switch active (repo config disabled)",
304: 			Duration: time.Since(start),
305: 		}, nil
306: 	}
307: 
308: 	repoID := entry.RepoID
309: 	if repoID == "" {
310: 		repoID, err = gitops.GenerateRepoID(entry.RootPath)
311: 		if err != nil {
312: 			return nil, fmt.Errorf("generating repo ID: %w", err)
313: 		}
314: 	}
315: 	repoRoot := entry.RootPath
316: 
317: 	// Ensure destination directory structure exists under <data-dir>/<repo-id>/
318: 	if err := config.EnsureDataDirLayout(dataDir, repoID); err != nil {
319: 		return nil, fmt.Errorf("ensuring data dir layout: %w", err)
320: 	}
321: 
322: 	// Query Git branch and HEAD commit (bounded by 50ms context timeout to preserve budget)
323: 	gitCtx, gitCancel := context.WithTimeout(ctx, 50*time.Millisecond)
324: 	branch, _ := gitops.GetCurrentBranchWithContext(gitCtx, repoRoot)
325: 	head, _ := gitops.GetHeadCommitWithContext(gitCtx, repoRoot)
326: 	gitCancel()
327: 
328: 	convID := payload.ConversationID
329: 	if convID == "" {
330: 		return &StopResult{
331: 			Skipped:  true,
332: 			Reason:   "conversation ID empty; no session to capture",
333: 			RepoID:   repoID,
334: 			RepoRoot: repoRoot,
335: 			Duration: time.Since(start),
336: 		}, nil
337: 	}
338: 
339: 	// Resolve transcript source path
340: 	transcriptPath := payload.TranscriptPath
341: 	if transcriptPath == "" {
342: 		transcriptPath = findBrainTranscript(convID)
343: 	}
344: 
345: 	// 5. Spool entry creation (using packages from WO1)
346: 	spoolDir := filepath.Join(dataDir, repoID, "spool")
347: 	captureEntry := spool.NewCaptureEntry("antigravity", convID, transcriptPath, repoRoot, branch, head)
348: 	parentConvID := opt.ParentConversationID
349: 	if parentConvID == "" {
350: 		parentConvID = payload.ParentConversationID
351: 	}
352: 	if parentConvID == "" && convSummary != nil {
353: 		parentConvID = convSummary.ParentConversationID
354: 	}
355: 	captureEntry.ParentConversationID = parentConvID
356: 	spoolPath, err := spool.Write(spoolDir, captureEntry)
357: 	if err != nil {
358: 		return nil, fmt.Errorf("writing capture spool entry: %w", err)
359: 	}
360: 
361: 	// 6. Incremental copy (using packages from WO1)
362: 	queueDir := filepath.Join(dataDir, repoID, "queue")
363: 	stateDir := filepath.Join(dataDir, repoID, "state")
364: 
365: 	var copyResult *spool.CopyResult
366: 	if transcriptPath != "" {
367: 		if _, err := os.Stat(transcriptPath); err == nil {
368: 			copyResult, err = spool.CopyTranscriptIncremental(convID, transcriptPath, queueDir, stateDir)
369: 			if err != nil {
370: 				return nil, fmt.Errorf("copying transcript incrementally: %w", err)
371: 			}
372: 		}
373: 	}
374: 
375: 	// 7. Artifact capture (best-effort per SPEC)
376: 	var artifactsCopied int
377: 	if payload.ArtifactDirectoryPath != "" {
378: 		artSrc := expandHome(payload.ArtifactDirectoryPath)
379: 		artDst := evidence.ArtifactDir(dataDir, repoID, convID)
380: 		
381: 		ch := make(chan int, 1)
382: 		go func() {
383: 			count, err := evidence.CopyArtifacts(artSrc, artDst)
384: 			if err != nil {
385: 				fmt.Fprintf(os.Stderr, "copying artifacts for %s: %v\n", convID, err)
386: 			}
387: 			ch <- count
388: 		}()
389: 
390: 		select {
391: 		case count := <-ch:
392: 			artifactsCopied = count
393: 		case <-time.After(100 * time.Millisecond):
394: 			// Timeout, let it run in background (will be killed when process exits)
395: 		}
396: 	}
397: 
398: 	duration := time.Since(start)
399: 	return &StopResult{
400: 		Skipped:              false,
401: 		ConversationID:       convID,
402: 		ParentConversationID: parentConvID,
403: 		RepoID:               repoID,
404: 		RepoRoot:             repoRoot,
